16	/// Complete the given command, shell-agnostic
17	pub fn complete(
18	    cmd: &mut clap::Command,
19	    args: Vec<OsString>,
20	    arg_index: usize,
21	    current_dir: Option<&std::path::Path>,
22	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
23	    debug!("complete: args={args:?}, arg_index={arg_index:?}, current_dir={current_dir:?}");
24	    cmd.build();
25	
26	    let raw_args = clap_lex::RawArgs::new(args);
27	    let mut cursor = raw_args.cursor();
28	    let mut target_cursor = raw_args.cursor();
29	    raw_args.seek(
30	        &mut target_cursor,
31	        clap_lex::SeekFrom::Start(arg_index as u64),
32	    );
33	    // As we loop, `cursor` will always be pointing to the next item
34	    raw_args.next_os(&mut target_cursor);
35	    debug!("complete: target_cursor={target_cursor:?}");
36	
37	    // TODO: Multicall support
38	    if !cmd.is_no_binary_name_set() {
39	        raw_args.next_os(&mut cursor);
40	    }
41	
42	    let mut current_cmd = &*cmd;
43	    let mut pos_index = 1;
44	    let mut is_escaped = false;
45	    let mut next_state = ParseState::ValueDone;
46	    // Set when an already closed word carried a value that cannot be part of
47	    // the command line (a delimiter-separated value set that is overfull, has
48	    // an empty segment, ...). Completion then reports "no completion generated"
49	    // instead of guessing at unrelated candidates.
50	    let mut is_illegal = false;
51	    // Ids of options explicitly present in `args[..arg_index]`, used to hide
52	    // conflicting candidates. Only recognized option names are recorded;
53	    // values, positionals, `--`-escaped words, default values and env values
54	    // never are.
55	    let mut explicit_opts = HashSet::<Id>::new();
56	    while let Some(arg) = raw_args.next(&mut cursor) {
57	        let current_state = next_state;
58	        next_state = ParseState::ValueDone;
59	        debug!(
60	            "complete::next: arg={:?}, current_state={current_state:?}, cursor={cursor:?}",
61	            arg.to_value_os(),
62	        );
63	        if cursor == target_cursor {
64	            if is_illegal {
65	                return Err(std::io::Error::other("no completion generated"));
66	            }
67	            let disabled = gather_disabled_args(current_cmd, &explicit_opts);
68	            return complete_arg(
69	                &arg,
70	                current_cmd,
71	                current_dir,
72	                pos_index,
73	                is_escaped,
74	                current_state,
75	                &disabled,
76	            );
77	        }
78	
79	        if let Ok(value) = arg.to_value() {
80	            // A dangling delimiter forces this word to be the option's next
81	            // segment, never a subcommand.
82	            let open_segment = matches!(&current_state, ParseState::Opt(state) if state.open);
83	            if !open_segment {
84	                if let Some(next_cmd) = current_cmd.find_subcommand(value) {
85	                    current_cmd = next_cmd;
86	                    pos_index = 1;
87	                    continue;
88	                }
89	            }
90	        }
91	
92	        // While a dangling delimiter makes the next segment mandatory
93	        // (`--opt=a,`), a closed word may only be that segment.  An option
94	        // word (recognized or not) or `--` cannot fill it and clap rejects the
95	        // line, so completion reports an error instead of guessing a stop or a
96	        // new option. An option with `allow_hyphen_values` still accepts a
97	        // hyphen-prefixed word as the segment. A plain value word below is
98	        // consumed as the segment.
99	        if let ParseState::Opt(state) = &current_state {
100	            if state.open && !is_escaped && !opt_allows_hyphen(&current_state, &arg) {
101	                let is_option_word = arg.is_escape()
102	                    || arg.to_long().is_some()
103	                    || arg
104	                        .to_short()
105	                        .is_some_and(|short| !short.is_negative_number());
106	                if is_option_word {
107	                    is_illegal = true;
108	                }
109	            }
110	        }
111	
112	        if is_escaped {
113	            (next_state, pos_index) =
114	                parse_positional(current_cmd, pos_index, is_escaped, current_state);
115	        } else if arg.is_escape() {
116	            is_escaped = true;
117	        } else if opt_allows_hyphen(&current_state, &arg) {
118	            match current_state {
119	                ParseState::Opt(state) => {
120	                    next_state = advance_opt_value(state, arg.to_value_os(), &mut is_illegal);
121	                }
122	                _ => unreachable!("else branch is only reachable in Opt state"),
123	            }
124	        } else if let Some((flag, value)) = arg.to_long() {
125	            if let Ok(flag) = flag {
126	                let opt = current_cmd.get_arguments().find(|a| {
127	                    let longs = a.get_long_and_visible_aliases();
128	                    let is_find = longs.map(|v| {
129	                        let mut iter = v.into_iter();
130	                        let s = iter.find(|s| *s == flag);
131	                        s.is_some()
132	                    });
133	                    is_find.unwrap_or(false)
134	                });
135	
136	                if let Some(opt) = opt {
137	                    explicit_opts.insert(opt.get_id().clone());
138	                    if opt.get_num_args().expect("built").takes_values() {
139	                        match value {
140	                            // A bare `--name` still expects its value as the next word.
141	                            None => next_state = ParseState::Opt(OptState::new(opt, 1)),
142	                            // A closed `--name=value` word normally ends the
143	                            // occurrence, but a dangling value delimiter with
144	                            // room for another segment keeps accepting values.
145	                            Some(value) => {
146	                                next_state = attached_opt_state(opt, value, &mut is_illegal);
147	                            }
148	                        }
149	                    }
150	                } else if pos_allows_hyphen(current_cmd, pos_index) {
151	                    (next_state, pos_index) =
152	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
153	                }
154	            }
155	        } else if let Some(short) = arg.to_short() {
156	            let (leading_flags, takes_value_opt, mut short, cluster_valid) =
157	                parse_shortflags(current_cmd, short);
158	            // Only a cluster made entirely of recognized flags records state.
159	            // Splitting an invalid short string into known and unknown members
160	            // would be guesswork and could suppress conflicting candidates, so
161	            // invalid clusters keep the existing completion behavior; clap's
162	            // parser would reject them anyway.
163	            if cluster_valid {
164	                // Every recognized flag in the cluster was explicitly supplied.
165	                for flag in leading_flags.chars() {
166	                    if let Some(opt) = current_cmd.get_arguments().find(|a| {
167	                        a.get_short_and_visible_aliases()
168	                            .is_some_and(|shorts| shorts.contains(&flag))
169	                    }) {
170	                        explicit_opts.insert(opt.get_id().clone());
171	                    }
172	                }
173	            }
174	            if let Some(opt) = takes_value_opt {
175	                if let Some(remainder) = short.next_value_os() {
176	                    // A closed `-ovalue` / `-o=value` word; advance like the
177	                    // long `--opt=value` form.
178	                    let value = remainder.strip_prefix("=").unwrap_or(remainder);
179	                    next_state = attached_opt_state(opt, value, &mut is_illegal);
180	                } else {
181	                    next_state = ParseState::Opt(OptState::new(opt, 1));
182	                }
183	            } else if pos_allows_hyphen(current_cmd, pos_index) {
184	                (next_state, pos_index) =
185	                    parse_positional(current_cmd, pos_index, is_escaped, current_state);
186	            }
187	        } else {
188	            match current_state {
189	                ParseState::ValueDone | ParseState::Pos(..) => {
190	                    (next_state, pos_index) =
191	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
192	                }
193	                ParseState::Opt(state) => {
194	                    next_state = advance_opt_value(state, arg.to_value_os(), &mut is_illegal);
195	                }
196	            }
197	        }
198	    }
199	
200	    Err(std::io::Error::other("no completion generated"))
201	}
