203	#[derive(Debug, PartialEq, Eq, Clone)]
204	enum ParseState<'a> {
205	    /// Parsing a value done, there is no state to record.
206	    ValueDone,
207	
208	    /// Parsing a positional argument after `--`. `Pos(pos_index`, `takes_num_args`)
209	    Pos((usize, usize)),
210	
211	    /// Parsing a optional flag argument
212	    Opt(OptState<'a>),
213	}
214	
215	/// Ongoing state while an option still accepts value words.
216	#[derive(Debug, PartialEq, Eq, Clone)]
217	struct OptState<'a> {
218	    opt: &'a clap::Arg,
219	    /// Ordinal of the value word about to be consumed within this occurrence.
220	    /// A bare `--name` waiting for its first value starts at `1`; this is the
221	    /// value handed to [`ArgValueCompleter::complete_at`] as `arg_index + 1`,
222	    /// so it counts shell words and is unaffected by the value delimiter.
223	    word: usize,
224	    /// Delimiter segments already closed by earlier value words, in order.
225	    used: Vec<OsString>,
226	    /// The state was reached through a dangling value delimiter, so the next
227	    /// word is another segment of this option rather than an optional stop.
228	    open: bool,
229	}
230	
231	impl<'a> OptState<'a> {
232	    fn new(opt: &'a clap::Arg, word: usize) -> Self {
233	        Self {
234	            opt,
235	            word,
236	            used: Vec::new(),
237	            open: false,
238	        }
239	    }
240	}
241	
242	/// Whether an option carries several values split by a delimiter inside one
243	/// shell word *and* bounds how many such values it accepts.
244	///
245	/// An argument with the default range of one value may still pack an arbitrary
246	/// number of delimiter segments into its single word (clap's parser allows it),
247	/// and completion preserves that legacy behavior; only multi-value arguments
248	/// count segments against their range.
249	fn is_bounded_delimited(opt: &clap::Arg) -> Option<char> {
250	    let delim = opt.get_value_delimiter()?;
251	    if opt.get_num_args().expect("built").max_values() > 1 {
252	        Some(delim)
253	    } else {
254	        None
255	    }
256	}
257	
258	/// Split a shell value on its delimiter into its closed segments.
259	///
260	/// Returns `(segments, dangling)` where `dangling` is set when the value ends
261	/// with the delimiter: the final empty piece is the segment still being typed
262	/// rather than a closed (empty and therefore invalid) segment. Splitting works
263	/// on raw [`OsStr`] bytes, so invalid UTF-8 values are handled too.
264	fn split_delimited(value: &OsStr, delim: char) -> (Vec<&OsStr>, bool) {
265	    let mut buf = [0_u8; 4];
266	    let delim_str = delim.encode_utf8(&mut buf);
267	    let mut segments: Vec<&OsStr> = value.split(delim_str).collect();
268	    let dangling = value.contains(delim_str) && segments.last().is_some_and(|last| last.is_empty());
269	    if dangling {
270	        segments.pop();
271	    }
272	    (segments, dangling)
273	}
