275	/// Fold one closed value word into an option's ongoing value state.
276	///
277	/// `Ok(None)` means the occurrence is complete, `Ok(Some(state))` that another
278	/// value word is accepted and `Err(())` that the word cannot be part of a valid
279	/// command line (an empty delimiter segment or more segments than the option
280	/// accepts); the latter produces "no completion generated" rather than guesses.
281	fn consume_opt_word<'a>(
282	    prior: OptState<'a>,
283	    value: &OsStr,
284	    attached: bool,
285	) -> Result<Option<OptState<'a>>, ()> {
286	    let opt = prior.opt;
287	    let range = opt.get_num_args().expect("built");
288	    let max = range.max_values();
289	    let ordinal = prior.word;
290	    let mut used = prior.used;
291	
292	    let Some(delim) = is_bounded_delimited(opt) else {
293	        // Legacy behavior: count whole shell words against the range; whatever
294	        // is packed behind a delimiter does not extend or shorten the count.
295	        // An attached value always closes the occurrence.
296	        return Ok(if !attached && ordinal < max {
297	            Some(OptState {
298	                opt,
299	                word: ordinal + 1,
300	                used,
301	                open: false,
302	            })
303	        } else {
304	            None
305	        });
306	    };
307	
308	    let mut buf = [0_u8; 4];
309	    let delim_str = delim.encode_utf8(&mut buf);
310	    let (segments, dangling) = split_delimited(value, delim);
311	    // Empty pieces are only invalid once a delimiter actually separates
312	    // segments; a bare empty value (`--opt=`) keeps its old tolerant behavior.
313	    if value.contains(delim_str) && segments.iter().any(|s| s.is_empty()) {
314	        return Err(());
315	    }
316	    let closed = used.len() + segments.len();
317	    if closed > max || (closed == max && dangling) {
318	        return Err(());
319	    }
320	    used.extend(segments.iter().map(|s| s.to_os_string()));
321	
322	    // An attached value closes the occurrence unless a dangling delimiter
323	    // still accepts another segment; a space-separated word keeps accepting
324	    // values until the range is full.
325	    let accepts_more = dangling || (!attached && closed < max);
326	    Ok(if accepts_more {
327	        Some(OptState {
328	            opt,
329	            word: ordinal + 1,
330	            used,
331	            open: dangling,
332	        })
333	    } else {
334	        None
335	    })
336	}
337	
338	/// State after a closed `--opt=value` word: `ValueDone` when the occurrence is
339	/// complete, `Opt` when a dangling delimiter still accepts another segment.
340	/// Illegal values flag the whole command line as uncompletable.
341	fn attached_opt_state<'a>(
342	    opt: &'a clap::Arg,
343	    value: &OsStr,
344	    is_illegal: &mut bool,
345	) -> ParseState<'a> {
346	    match consume_opt_word(OptState::new(opt, 1), value, true) {
347	        Ok(Some(state)) => ParseState::Opt(state),
348	        Ok(None) => ParseState::ValueDone,
349	        Err(()) => {
350	            *is_illegal = true;
351	            ParseState::ValueDone
352	        }
353	    }
354	}
355	
356	/// Advance an ongoing option occurrence by one space-separated value word.
357	fn advance_opt_value<'a>(
358	    state: OptState<'a>,
359	    value: &OsStr,
360	    is_illegal: &mut bool,
361	) -> ParseState<'a> {
362	    match consume_opt_word(state, value, false) {
363	        Ok(Some(next)) => ParseState::Opt(next),
364	        Ok(None) => ParseState::ValueDone,
365	        Err(()) => {
366	            *is_illegal = true;
367	            ParseState::ValueDone
368	        }
369	    }
370	}
