372	/// Result of analyzing the value word under the cursor for an option that
373	/// packs delimiter-separated values.
374	struct DelimCursor<'s> {
375	    /// Text of the segment currently being typed.
376	    current: &'s OsStr,
377	    /// Closed segments that precede it, in order.
378	    closed: Vec<&'s OsStr>,
379	    /// Everything in this shell word before the current segment, including the
380	    /// trailing delimiter, to re-prefix candidates with.
381	    prefix: &'s str,
382	}
383	
384	/// Split the cursor value of a bounded delimiter option into the segment being
385	/// edited and its already closed prefix segments.
386	///
387	/// `Ok(None)` means the option is not a bounded delimiter option (legacy
388	/// completion applies); `Err(())` means the cursor sits at an illegal segment
389	/// position (a leading/empty segment or one past the accepted number of
390	/// values), which must not produce candidates.
391	fn cursor_delimited<'s>(
392	    opt: &clap::Arg,
393	    value: &'s OsStr,
394	    prior_segments: usize,
395	) -> Result<Option<DelimCursor<'s>>, ()> {
396	    let Some(delim) = is_bounded_delimited(opt) else {
397	        return Ok(None);
398	    };
399	    let max = opt.get_num_args().expect("built").max_values();
400	    // The cursor word being edited keeps the legacy whole-word completion when
401	    // it is not valid UTF-8; earlier closed words are still tracked by bytes.
402	    let value_str = match value.to_str() {
403	        Some(s) => s,
404	        None => return Ok(None),
405	    };
406	    let mut buf = [0_u8; 4];
407	    let delim_str = delim.encode_utf8(&mut buf);
408	
409	    let Some(pos) = value_str.rfind(delim) else {
410	        return Ok(Some(DelimCursor {
411	            current: value,
412	            closed: Vec::new(),
413	            prefix: "",
414	        }));
415	    };
416	    let (prefix, current) = value_str.split_at(pos + delim.len_utf8());
417	    let closed: Vec<&str> = prefix[..prefix.len() - delim_str.len()]
418	        .split(delim)
419	        .collect();
420	    if closed.iter().any(|s| s.is_empty()) || prior_segments + closed.len() >= max {
421	        return Err(());
422	    }
423	    Ok(Some(DelimCursor {
424	        current: OsStr::new(current),
425	        closed: closed.into_iter().map(OsStr::new).collect(),
426	        prefix,
427	    }))
428	}
