430	fn complete_arg(
431	    arg: &clap_lex::ParsedArg<'_>,
432	    cmd: &clap::Command,
433	    current_dir: Option<&std::path::Path>,
434	    pos_index: usize,
435	    is_escaped: bool,
436	    state: ParseState<'_>,
437	    disabled: &HashSet<Id>,
438	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
439	    debug!(
440	        "complete_arg: arg={:?}, cmd={:?}, current_dir={:?}, pos_index={:?}, state={:?}",
441	        arg,
442	        cmd.get_name(),
443	        current_dir,
444	        pos_index,
445	        state
446	    );
447	    let mut completions = Vec::<CompletionCandidate>::new();
448	
449	    match state {
450	        ParseState::ValueDone => {
451	            // A closed `--name=value` word (or a short cluster carrying an
452	            // inline value, e.g. `-ovalue` / `-o=value`) is the option's value
453	            // position: only the option's own values are completed, exactly as
454	            // if the value had been written as a separate word.  The content
455	            // after `=` never takes part in subcommand, positional or
456	            // option-name completion, and the word itself is not yet part of
457	            // the conflict set.
458	            if !is_escaped {
459	                if let Some(values) = complete_inline_option_value(arg, cmd, current_dir, disabled)
460	                {
461	                    let values =
462	                        values.map_err(|()| std::io::Error::other("no completion generated"))?;
463	                    completions.extend(values);
464	                    return finalize_completions(completions);
465	                }
466	            }
467	
468	            // After `--`, only positional arguments are completed.
469	            if !is_escaped {
470	                if let Ok(value) = arg.to_value() {
471	                    completions.extend(complete_subcommand(value, cmd));
472	                }
473	            }
474	
475	            if let Some(positional) = cmd
476	                .get_positionals()
477	                .find(|p| p.get_index() == Some(pos_index))
478	            {
479	                if !disabled.contains(positional.get_id()) {
480	                    completions.extend(complete_arg_value(
481	                        arg.to_value(),
482	                        positional,
483	                        current_dir,
484	                        0,
485	                    ));
486	                }
487	            }
488	            if !is_escaped {
489	                completions.extend(complete_option(arg, cmd, current_dir, disabled));
490	            }
491	        }
492	        ParseState::Pos((_, num_arg)) => {
493	            if let Some(positional) = cmd
494	                .get_positionals()
495	                .find(|p| p.get_index() == Some(pos_index))
496	            {
497	                if !disabled.contains(positional.get_id()) {
498	                    completions.extend(complete_arg_value(
499	                        arg.to_value(),
500	                        positional,
501	                        current_dir,
502	                        num_arg.saturating_sub(1),
503	                    ));
504	                }
505	                if !is_escaped
506	                    && positional
507	                        .get_num_args()
508	                        .is_some_and(|num_args| num_arg >= num_args.min_values())
509	                {
510	                    completions.extend(complete_option(arg, cmd, current_dir, disabled));
511	                }
512	            }
513	        }
514	        ParseState::Opt(state) => {
515	            let opt = state.opt;
516	            if !disabled.contains(opt.get_id()) {
517	                match complete_separate_opt_value(arg.to_value(), &state, current_dir) {
518	                    Ok(values) => completions.extend(values),
519	                    // The cursor sits at an illegal segment position (an empty
520	                    // segment or one past the accepted number of values).
521	                    Err(()) => return Err(std::io::Error::other("no completion generated")),
522	                }
523	            }
524	            let min = opt.get_num_args().map(|r| r.min_values()).unwrap_or(0);
525	            if state.word > min && !state.open {
526	                // Also complete this raw_arg as a positional argument, flags,
527	                // options and subcommand.  A dangling delimiter (`state.open`)
528	                // requires the next word to be this option's segment: it cannot
529	                // be a valid stop, so nothing else is offered there.
530	                completions.extend(complete_arg(
531	                    arg,
532	                    cmd,
533	                    current_dir,
534	                    pos_index,
535	                    is_escaped,
536	                    ParseState::ValueDone,
537	                    disabled,
538	                )?);
539	            }
540	        }
541	    }
542	
543	    finalize_completions(completions)
544	}
