546	/// Hide hidden candidates when visible ones exist, deduplicate by id and sort
547	/// into the presentation order shared by every completion source.
548	fn finalize_completions(
549	    mut completions: Vec<CompletionCandidate>,
550	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
551	    if completions.iter().any(|a| !a.is_hide_set()) {
552	        completions.retain(|a| !a.is_hide_set());
553	    }
554	    let mut seen_ids = HashSet::new();
555	    completions.retain(move |a| {
556	        if let Some(id) = a.get_id().cloned() {
557	            seen_ids.insert(id)
558	        } else {
559	            true
560	        }
561	    });
562	
563	    let mut tags = Vec::new();
564	    for candidate in &completions {
565	        let tag = candidate.get_tag().cloned();
566	        if !tags.contains(&tag) {
567	            tags.push(tag);
568	        }
569	    }
570	    completions.sort_by_key(|c| {
571	        (
572	            tags.iter().position(|t| c.get_tag() == t.as_ref()),
573	            c.get_display_order(),
574	        )
575	    });
576	
577	    Ok(completions)
578	}
579	
580	/// Generate value candidates for the segment under the cursor of a
581	/// delimiter-separated multi-value option.
582	///
583	/// `prior_segments` is the number of segments already closed by earlier shell
584	/// words; `prior_used` are their literal values, suppressed from the result so
585	/// an already selected value is not offered a second time.  Candidates cover
586	/// only the current shell word, so `prefix` from closed segments is limited to
587	/// the current word as well.
588	///
589	/// `Ok` carries the candidates; `Err(())` marks an illegal segment position
590	/// (an empty segment or a segment past the accepted number of values).
591	fn complete_segment_value(
592	    value: &OsStr,
593	    opt: &clap::Arg,
594	    prior_segments: usize,
595	    prior_used: &[&OsStr],
596	    arg_index: usize,
597	    current_dir: Option<&std::path::Path>,
598	) -> Result<Vec<CompletionCandidate>, ()> {
599	    let Some(cursor) = cursor_delimited(opt, value, prior_segments)? else {
600	        // Not a bounded delimiter option: keep the legacy whole-word
601	        // completion (its own `rsplit_delimiter` handles single-value args).
602	        return Ok(complete_arg_value(
603	            value.to_str().ok_or(value),
604	            opt,
605	            current_dir,
606	            arg_index,
607	        ));
608	    };
609	
610	    let mut used: Vec<&OsStr> = prior_used.to_vec();
611	    used.extend(cursor.closed.iter().copied());
612	
613	    let mut values = complete_arg_value(
614	        Ok(cursor.current.to_str().ok_or(())?),
615	        opt,
616	        current_dir,
617	        arg_index,
618	    );
619	    // An already closed segment stays selected and must not reappear.
620	    values.retain(|comp| !used.iter().any(|u| *u == comp.get_value()));
621	    if !cursor.prefix.is_empty() {
622	        values = values
623	            .into_iter()
624	            .map(|comp| comp.add_prefix(cursor.prefix))
625	            .collect();
626	    }
627	    Ok(values)
628	}
