848	fn complete_arg_value(
849	    value: Result<&str, &OsStr>,
850	    arg: &clap::Arg,
851	    current_dir: Option<&std::path::Path>,
852	    arg_index: usize,
853	) -> Vec<CompletionCandidate> {
854	    let mut values = Vec::new();
855	    debug!("complete_arg_value: arg={arg:?}, value={value:?}, arg_index={arg_index:?}");
856	
857	    let (prefix, value) =
858	        rsplit_delimiter(value, arg.get_value_delimiter()).unwrap_or((None, value));
859	
860	    let value_os = match value {
861	        Ok(value) => OsStr::new(value),
862	        Err(value_os) => value_os,
863	    };
864	
865	    if let Some(completer) = arg.get::<ArgValueCompleter>() {
866	        values.extend(completer.complete_at(arg_index, value_os));
867	    } else if let Some(completer) = arg.get::<ArgValueCandidates>() {
868	        values.extend(complete_value_candidates(
869	            value_os,
870	            completer.value_candidates(),
871	        ));
872	    } else if let Some(possible_values) = possible_values(arg) {
873	        if let Ok(value) = value {
874	            values.extend(complete_candidates_str(
875	                value,
876	                possible_value_candidates(possible_values),
877	            ));
878	        }
879	    } else {
880	        match arg.get_value_hint() {
881	            clap::ValueHint::Unknown | clap::ValueHint::Other => {
882	                // Should not complete
883	            }
884	            clap::ValueHint::AnyPath => {
885	                values.extend(complete_path(value_os, current_dir, &|_| true));
886	            }
887	            clap::ValueHint::FilePath => {
888	                values.extend(complete_path(value_os, current_dir, &|p| p.is_file()));
889	            }
890	            clap::ValueHint::DirPath => {
891	                values.extend(complete_path(value_os, current_dir, &|p| p.is_dir()));
892	            }
893	            clap::ValueHint::ExecutablePath => {
894	                use is_executable::IsExecutable;
895	                values.extend(complete_path(value_os, current_dir, &|p| p.is_executable()));
896	            }
897	            clap::ValueHint::CommandName
898	            | clap::ValueHint::CommandString
899	            | clap::ValueHint::CommandWithArguments
900	            | clap::ValueHint::Username
901	            | clap::ValueHint::Hostname
902	            | clap::ValueHint::Url
903	            | clap::ValueHint::EmailAddress => {
904	                // No completion implementation
905	            }
906	            _ => {
907	                // Safe-ish fallback
908	                values.extend(complete_path(value_os, current_dir, &|_| true));
909	            }
910	        }
911	
912	        values.sort();
913	    }
914	
915	    if let Some(prefix) = prefix {
916	        values = values
917	            .into_iter()
918	            .map(|comp| comp.add_prefix(prefix))
919	            .collect();
920	    }
921	    values = values
922	        .into_iter()
923	        .map(|comp| {
924	            if comp.get_tag().is_some() {
925	                comp
926	            } else {
927	                comp.tag(Some(arg.to_string().into()))
928	            }
929	        })
930	        .collect();
931	
932	    debug!("complete_arg_value: values={values:?}");
933	    values
934	}
