1129	/// Parse the short flags and find the first `takes_values` option.
1130	///
1131	/// The returned bool is `true` only when every scanned cluster member was a
1132	/// recognized option. Anything after the first value-taking option is the
1133	/// option's value and therefore not scanned; invalid UTF-8 and unknown short
1134	/// characters make the result `false`.
1135	fn parse_shortflags<'c, 's>(
1136	    cmd: &'c clap::Command,
1137	    mut short: clap_lex::ShortFlags<'s>,
1138	) -> (
1139	    String,
1140	    Option<&'c clap::Arg>,
1141	    clap_lex::ShortFlags<'s>,
1142	    bool,
1143	) {
1144	    let takes_value_opt;
1145	    let mut leading_flags = String::new();
1146	    let mut cluster_valid = true;
1147	    // Find the first takes_values option.
1148	    loop {
1149	        match short.next_flag() {
1150	            Some(Ok(opt)) => {
1151	                leading_flags.push(opt);
1152	                let found = cmd.get_arguments().find(|a| {
1153	                    let shorts = a.get_short_and_visible_aliases();
1154	                    let is_find = shorts.map(|v| {
1155	                        let mut iter = v.into_iter();
1156	                        let c = iter.find(|c| *c == opt);
1157	                        c.is_some()
1158	                    });
1159	                    is_find.unwrap_or(false)
1160	                });
1161	                if let Some(opt) = found {
1162	                    if opt.get_num_args().expect("built").takes_values() {
1163	                        takes_value_opt = Some(opt);
1164	                        break;
1165	                    }
1166	                } else {
1167	                    cluster_valid = false;
1168	                }
1169	            }
1170	            Some(Err(_)) => {
1171	                cluster_valid = false;
1172	                takes_value_opt = None;
1173	                break;
1174	            }
1175	            None => {
1176	                takes_value_opt = None;
1177	                break;
1178	            }
1179	        }
1180	    }
1181	
1182	    (leading_flags, takes_value_opt, short, cluster_valid)
1183	}
1184	
1185	/// Parse the positional arguments. Return the new state and the new positional index.
1186	fn parse_positional<'a>(
1187	    cmd: &clap::Command,
1188	    pos_index: usize,
1189	    is_escaped: bool,
1190	    state: ParseState<'a>,
1191	) -> (ParseState<'a>, usize) {
1192	    let pos_arg = cmd
1193	        .get_positionals()
1194	        .find(|p| p.get_index() == Some(pos_index));
1195	    let num_args = pos_arg
1196	        .and_then(|a| a.get_num_args().map(|r| r.max_values()))
1197	        .unwrap_or(1);
1198	
1199	    let update_state_with_new_positional = |pos_index| -> (ParseState<'a>, usize) {
1200	        if num_args > 1 {
1201	            (ParseState::Pos((pos_index, 1)), pos_index)
1202	        } else {
1203	            if is_escaped {
1204	                (ParseState::Pos((pos_index, 1)), pos_index + 1)
1205	            } else {
1206	                (ParseState::ValueDone, pos_index + 1)
1207	            }
1208	        }
1209	    };
1210	    match state {
1211	        ParseState::ValueDone => {
1212	            update_state_with_new_positional(pos_index)
1213	        },
1214	        ParseState::Pos((prev_pos_index, num_arg)) => {
1215	            if prev_pos_index == pos_index {
1216	                if num_arg + 1 < num_args {
1217	                    (ParseState::Pos((pos_index, num_arg + 1)), pos_index)
1218	                } else {
1219	                    if is_escaped {
1220	                        (ParseState::Pos((pos_index, 1)), pos_index + 1)
1221	                    } else {
1222	                        (ParseState::ValueDone, pos_index + 1)
1223	                    }
1224	                }
1225	            } else {
1226	                update_state_with_new_positional(pos_index)
1227	            }
1228	        }
1229	        ParseState::Opt(..) => unreachable!(
1230	            "This branch won't be hit,
1231	            because ParseState::Opt should not be seen as a positional argument and passed to this function."
1232	        ),
1233	    }
1234	}
1235	
1236	fn pos_allows_hyphen(cmd: &clap::Command, pos_index: usize) -> bool {
1237	    cmd.get_positionals()
1238	        .find(|a| a.get_index() == Some(pos_index))
1239	        .map(|p| p.is_allow_hyphen_values_set())
1240	        .unwrap_or(false)
1241	}
1242	
1243	fn opt_allows_hyphen(state: &ParseState<'_>, arg: &clap_lex::ParsedArg<'_>) -> bool {
1244	    let val = arg.to_value_os();
1245	    if val.starts_with("-") {
1246	        if let ParseState::Opt(state) = state {
1247	            return state.opt.is_allow_hyphen_values_set();
1248	        }
1249	    }
1250	
1251	    false
1252	}
1253	
1254	/// Arguments that must not be offered because they conflict with an explicitly
1255	/// present option. The present options themselves are never disabled.
1256	fn gather_disabled_args(cmd: &clap::Command, explicit: &HashSet<Id>) -> HashSet<Id> {
1257	    let mut disabled = HashSet::new();
1258	    if explicit.is_empty() {
1259	        return disabled;
1260	    }
1261	    for arg in cmd.get_arguments() {
1262	        if explicit.contains(arg.get_id()) {
1263	            // A present option hides everything it conflicts with ...
1264	            for id in arg_direct_conflicts(cmd, arg) {
1265	                if !explicit.contains(&id) {
1266	                    disabled.insert(id);
1267	                }
1268	            }
1269	        } else {
1270	            // ... and is hidden when either side declares the conflict.
1271	            if arg_direct_conflicts(cmd, arg)
1272	                .iter()
1273	                .any(|id| explicit.contains(id))
1274	            {
1275	                disabled.insert(arg.get_id().clone());
1276	            }
1277	        }
1278	    }
1279	    disabled
1280	}
1281	
1282	/// Conflict partners of `arg`, following the same rules as clap's parser:
1283	/// - the argument's own `conflicts_with` / `conflicts_with_all`
1284	/// - `conflicts_with` / `conflicts_with_all` of every group the argument belongs to
1285	/// - the other members of non-`multiple` groups
1286	///
1287	/// Group ids are expanded to their argument members.
1288	/// `overrides_with` relationships are intentionally not considered.
1289	fn arg_direct_conflicts(cmd: &clap::Command, arg: &clap::Arg) -> HashSet<Id> {
1290	    let mut conflicts = arg
1291	        .get_conflicts_with()
1292	        .map(ToOwned::to_owned)
1293	        .collect::<HashSet<_>>();
1294	    for group in cmd.get_groups() {
1295	        let members = unroll_group(cmd, group.get_id());
1296	        if !members.iter().any(|m| m == arg.get_id()) {
1297	            continue;
1298	        }
1299	        conflicts.extend(group.get_conflicts_with().map(ToOwned::to_owned));
1300	        if !group.is_multiple_set() {
1301	            conflicts.extend(members.into_iter().filter(|m| m != arg.get_id()));
1302	        }
1303	    }
1304	    conflicts
1305	        .iter()
1306	        .flat_map(|id| unroll_group(cmd, id))
1307	        .collect()
1308	}
1309	
1310	/// Resolve an argument or group id to its argument members.
1311	/// Unknown ids resolve to themselves.
1312	fn unroll_group(cmd: &clap::Command, id: &Id) -> Vec<Id> {
1313	    let mut pending = vec![id.clone()];
1314	    let mut args = Vec::new();
1315	    while let Some(id) = pending.pop() {
1316	        if cmd.get_arguments().any(|a| a.get_id() == &id) {
1317	            if !args.contains(&id) {
1318	                args.push(id);
1319	            }
1320	        } else if let Some(group) = cmd.get_groups().find(|g| g.get_id() == &id) {
1321	            pending.extend(group.get_args().map(ToOwned::to_owned));
1322	        } else if !args.contains(&id) {
1323	            args.push(id);
1324	        }
1325	    }
1326	    args
1327	}
